<?php require_once __DIR__.'/../api/bootstrap.php'; require_login(); $m=current_medico(); $id=(int)($_GET['id']??0); $p=patient_for_doctor($id,$m['id']); if(!$p)exit('Paciente não encontrado.'); $s=db()->prepare('SELECT * FROM atendimentos WHERE paciente_id=? AND medico_id=? ORDER BY data_atendimento DESC'); $s->execute([$id,$m['id']]); $ats=$s->fetchAll(); $s=db()->prepare('SELECT id,titulo,data_emissao,status,codigo_validacao FROM atestados WHERE paciente_id=? AND medico_id=? ORDER BY data_emissao DESC'); $s->execute([$id,$m['id']]); $atsd=$s->fetchAll(); $s=db()->prepare('SELECT id,titulo,data_emissao,status,codigo_validacao FROM laudos WHERE paciente_id=? AND medico_id=? ORDER BY data_emissao DESC'); $s->execute([$id,$m['id']]); $laudos=$s->fetchAll(); render_header('Prontuário'); ?><h1>Prontuário · <?=e($p['nome'])?></h1><div class="card"><div class="grid"><div><b>CPF:</b> <?=e($p['cpf'])?></div><div><b>Nascimento:</b> <?=e($p['data_nascimento'])?></div><div><b>Telefone:</b> <?=e($p['telefone'])?></div><div><b>Profissão:</b> <?=e($p['profissao'])?></div><div><b>Função:</b> <?=e($p['funcao'])?></div><div><b>Empresa:</b> <?=e($p['empresa'])?></div></div><p><b>Alergias:</b> <?=nl2br(e($p['alergias']))?></p><p><b>Medicamentos:</b> <?=nl2br(e($p['medicamentos']))?></p><p><b>Antecedentes:</b> <?=nl2br(e($p['antecedentes']))?></p></div><div class="card"><h2>Atendimentos</h2><?php foreach($ats as $a): ?><p><b><?=e(date('d/m/Y H:i',strtotime($a['data_atendimento'])))?></b> — <?=e($a['queixa_principal'])?> · <a href="<?=e(medical_url('atestados/create.php?atendimento_id='.$a['id']))?>">Atestado</a> · <a href="<?=e(medical_url('laudos/create.php?atendimento_id='.$a['id']))?>">Laudo</a></p><?php endforeach; if(!$ats): ?><p class="muted">Nenhum atendimento.</p><?php endif; ?></div><div class="card"><h2>Documentos emitidos</h2><?php foreach($atsd as $a): ?><p>Atestado · <?=e($a['titulo'])?> · <?=e($a['status'])?> · <a href="<?=e(medical_url('atestados/view.php?id='.$a['id']))?>">Abrir</a></p><?php endforeach; foreach($laudos as $l): ?><p>Laudo · <?=e($l['titulo'])?> · <?=e($l['status'])?> · <a href="<?=e(medical_url('laudos/view.php?id='.$l['id']))?>">Abrir</a></p><?php endforeach; if(!$atsd&&!$laudos): ?><p class="muted">Nenhum documento.</p><?php endif; ?></div><a class="btn" href="<?=e(medical_url('pacientes/edit.php?id='.$p['id']))?>">Editar paciente</a> <?php render_footer(); ?>